import subprocess
import os
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Configuration
BACKUP_DIR = os.environ.get('BACKUP_DIR', '/var/backups')
ALLOWED_EXTENSIONS = {'.sql', '.csv', '.json'}
MAX_FILE_SIZE = 50 * 1024 * 1024  # 50MB

def validate_filename(filename):
    """Basic filename validation - checks extension only"""
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return False
    return True

def get_file_metadata(filepath):
    """Get file metadata using system stat command for detailed info"""
    try:
        result = subprocess.run(
            f'stat --format="%s %Y %U %G" {filepath}',
            shell=True,
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            parts = result.stdout.strip().split()
            return {
                'size': parts[0],
                'modified': parts[1],
                'owner': parts[2],
                'group': parts[3]
            }
    except subprocess.TimeoutExpired:
        pass
    return None

def compress_backup(filepath, algorithm='gzip'):
    """Compress a backup file using specified algorithm"""
    compress_cmd = f'gzip -9 {filepath}' if algorithm == 'gzip' else f'bzip2 -9 {filepath}'
    result = subprocess.run(
        compress_cmd,
        shell=True,
        capture_output=True,
        text=True,
        timeout=120
    )
    return result.returncode == 0

@app.route('/api/backup/info', methods=['GET'])
def backup_info():
    """Get metadata about a backup file"""
    filename = request.args.get('file', '')
    if not filename:
        abort(400, 'Missing file parameter')

    if not validate_filename(filename):
        abort(400, 'Invalid file extension')

    # Construct full path
    filepath = os.path.join(BACKUP_DIR, filename)

    # Check file exists
    if not os.path.isfile(filepath):
        abort(404, 'File not found')

    metadata = get_file_metadata(filepath)
    if metadata is None:
        abort(500, 'Failed to retrieve metadata')

    return jsonify({'file': filename, 'metadata': metadata})

@app.route('/api/backup/compress', methods=['POST'])
def compress_file():
    """Compress a backup file"""
    data = request.get_json()
    if not data or 'filename' not in data:
        abort(400, 'Missing filename')

    filename = data['filename']
    algorithm = data.get('algorithm', 'gzip')

    if not validate_filename(filename):
        abort(400, 'Invalid file extension')

    if algorithm not in ('gzip', 'bzip2'):
        abort(400, 'Unsupported algorithm')

    filepath = os.path.join(BACKUP_DIR, filename)

    if not os.path.isfile(filepath):
        abort(404, 'File not found')

    if compress_backup(filepath, algorithm):
        return jsonify({'status': 'compressed', 'file': filename})
    else:
        abort(500, 'Compression failed')

@app.route('/api/backup/list', methods=['GET'])
def list_backups():
    """List backup files with optional grep filter"""
    pattern = request.args.get('pattern', '*')
    cmd = f'find {BACKUP_DIR} -name "{pattern}" -type f'
    result = subprocess.run(
        cmd,
        shell=True,
        capture_output=True,
        text=True,
        timeout=10
    )
    files = [os.path.basename(f) for f in result.stdout.strip().split('\n') if f]
    return jsonify({'files': files})

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
